// generatedFixtureRepo builds a branch that mixes one hand-written file with
// generated output found by each detection rule: gitattributes, the
// "Code generated" header, a configured glob, and compressed or map siblings.
func generatedFixtureRepo(t *testing.T) (dir string, generated []string) {
	t.Helper()
	dir = t.TempDir()
	gitInCmd(t, dir, "init", "-q", "-b", "main")
	write := func(rel, body string) {
		t.Helper()
		full := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("README.md", "# fixture\n")
	gitInCmd(t, dir, "add", ".")
	gitInCmd(t, dir, "commit", "-q", "-m", "init")
	gitInCmd(t, dir, "checkout", "-q", "-b", "feature")

	write(".gitattributes", "fixtures/perf-loader/** linguist-generated=true\n")
	write("src/app.go", "package src\n\nfunc App() int { return 1 }\n")
	for i := 0; i < 30; i++ {
		html := fmt.Sprintf("fixtures/perf-loader/case-%02d.html", i)
		json := fmt.Sprintf("fixtures/perf-loader/case-%02d.json", i)
		write(html, fmt.Sprintf("<html>case %d</html>\n", i))
		write(json, fmt.Sprintf("{\"case\": %d}\n", i))
		generated = append(generated, html, json)
	}
	write("client/patch.js", "export const patch = 1;\n")
	write("client/patch.js.br", "br-compressed-placeholder\n")
	write("client/patch.js.gz", "gz-compressed-placeholder\n")
	write("client/patch.js.map", "{\"version\":3}\n")
	write("gen/types.go", "// Code generated by gentypes. DO NOT EDIT.\n\npackage gen\n\ntype T int\n")
	write("schema/types.gen.txt", "configured generated output\n")
	generated = append(generated,
		"client/patch.js", "client/patch.js.br", "client/patch.js.gz", "client/patch.js.map",
		"gen/types.go", "schema/types.gen.txt")
	gitInCmd(t, dir, "add", ".")
	gitInCmd(t, dir, "commit", "-q", "-m", "regenerate fixtures")

	diffsignal.SetGeneratedResolver(diffsignal.NewGeneratedResolver(dir, []string{"*.gen.txt"}))
	t.Cleanup(func() { diffsignal.SetGeneratedResolver(nil) })
	return dir, generated
}

func TestBuildBranchPrompt_GeneratedFilesCollapseToGroups(t *testing.T) {
	dir, generated := generatedFixtureRepo(t)
	t.Chdir(dir)

	ctx, _, err := AssembleBranchContext(BranchContextOptions{
		MaxDiffBytes: 1_000_000,
		BaseBranch:   "main",
		Scope:        ReviewScopeBranch,
	})
	if err != nil {
		t.Fatalf("AssembleBranchContext: %v", err)
	}
	prompt := BuildBranchPrompt(ctx)

	// A single generated file renders as its own summary line, so check the
	// per-file listing and the groups separately.
	start := strings.Index(prompt, "## Files Changed")
	end := strings.Index(prompt, "## Generated Files")
	if start < 0 || end < start {
		t.Fatalf("prompt lacks Files Changed or Generated Files section:\n%.2000s", prompt)
	}
	listing := prompt[start:end]
	for _, path := range generated {
		if strings.Contains(listing, path) {
			t.Errorf("per-file listing includes generated file %q", path)
		}
	}
	for i := 0; i < 30; i++ {
		if name := fmt.Sprintf("case-%02d", i); strings.Contains(prompt, name) {
			t.Errorf("prompt names grouped file %q", name)
		}
	}
	for _, want := range []string{
		"src/app.go",
		"fixtures/perf-loader/*.html | 30 files",
		"fixtures/perf-loader/*.json | 30 files",
		"## Generated Files",
	} {
		if !strings.Contains(prompt, want) {
			t.Errorf("prompt missing %q", want)
		}
	}
}

func TestBranchContext_GeneratedFilesLeaveTheLedger(t *testing.T) {
	dir, generated := generatedFixtureRepo(t)
	t.Chdir(dir)

	ctx, _, err := AssembleBranchContext(BranchContextOptions{
		MaxDiffBytes: 1_000_000,
		BaseBranch:   "main",
		Scope:        ReviewScopeBranch,
	})
	if err != nil {
		t.Fatalf("AssembleBranchContext: %v", err)
	}
	if got := len(ctx.GeneratedFiles); got != len(generated) {
		t.Fatalf("GeneratedFiles = %d, want %d: %v", got, len(generated), ctx.GeneratedFiles)
	}
	changed := make([]string, 0, len(ctx.Files))
	for _, f := range ctx.Files {
		changed = append(changed, f.Path)
	}
	entries := []CoverageEntry{
		{Path: ".gitattributes", Evidence: "attribute marks fixtures generated"},
		{Path: "src/app.go", Evidence: "src/app.go:3 returns 1"},
	}

	// Before the fix the ledger had to list all 68 changed paths.
	if err := validateCoverageLedger(entries, changed); err == nil {
		t.Fatal("ledger without generated files validated against the full file list; the fixture is not exercising the failure")
	}
	if err := validateCoverageLedgerExcluding(entries, changed, ctx.GeneratedFiles); err != nil {
		t.Fatalf("ledger without generated files rejected: %v", err)
	}
	if got := ledgerPaths(changed, ctx.GeneratedFiles); len(got) != 2 {
		t.Fatalf("ledgerPaths() = %v, want .gitattributes and src/app.go", got)
	}
}

func TestValidateCoverageLedgerExcluding_ModelListsGeneratedFiles(t *testing.T) {
	changed := []string{"src/app.go", "fx/a.html", "fx/b.html", "dist/x.js"}
	generated := []string{"fx/a.html", "fx/b.html", "dist/x.js"}
	for name, extra := range map[string]CoverageEntry{
		"exact path": {Path: "fx/a.html", Evidence: "regenerated"},
		"glob":       {Path: "fx/*.html", Evidence: "regenerated"},
		"directory":  {Path: "dist/**", Evidence: "bundle"},
	} {
		t.Run(name, func(t *testing.T) {
			entries := []CoverageEntry{{Path: "src/app.go", Evidence: "src/app.go:1"}, extra}
			if err := validateCoverageLedgerExcluding(entries, changed, generated); err != nil {
				t.Fatalf("entry naming only generated files rejected: %v", err)
			}
		})
	}
	t.Run("hand-written file still required", func(t *testing.T) {
		err := validateCoverageLedgerExcluding([]CoverageEntry{{Path: "fx/*.html", Evidence: "x"}}, changed, generated)
		if err == nil || !strings.Contains(err.Error(), "missing src/app.go") {
			t.Fatalf("error = %v, want missing src/app.go", err)
		}
	})
	t.Run("unknown path still unexpected", func(t *testing.T) {
		entries := []CoverageEntry{{Path: "src/app.go", Evidence: "x"}, {Path: "other.go", Evidence: "x"}}
		err := validateCoverageLedgerExcluding(entries, changed, generated)
		if err == nil || !strings.Contains(err.Error(), "unexpected other.go") {
			t.Fatalf("error = %v, want unexpected other.go", err)
		}
	})
}

func TestGeneratedSummary_ShowsReceiptCoverage(t *testing.T) {
	groups := []diffsignal.GeneratedGroup{
		{Pattern: "fx/*.html", Files: []string{"fx/a.html", "fx/b.html"}, Bytes: 2048},
		{Pattern: "dist/*.js", Files: []string{"dist/x.js", "dist/y.js"}, Bytes: 100},
		{Pattern: "dist/z.map", Files: []string{"dist/z.map"}, Bytes: 10},
	}
	report := &VerificationReport{
		Covered: []EvidenceItem{{Kind: "receipt", Paths: []string{"fx/a.html", "fx/b.html", "dist/x.js"}}},
		Failing: []EvidenceItem{{Kind: "ci", Paths: []string{"dist/z.map"}}},
	}
	got := GeneratedSummary(groups, report)
	for _, want := range []string{
		"## Generated Files",
		"`fx/*.html`: 2 files, 2.0 KB changed; covered by a receipt (2 of 2)",
		"`dist/*.js`: 2 files, 100 B changed; covered by a receipt for 1 of 2",
		"`dist/z.map`: 1 file, 10 B changed; receipt failing for 1 of 1",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("summary missing %q:\n%s", want, got)
		}
	}
	if none := GeneratedSummary(groups[:1], nil); !strings.Contains(none, "not covered by any receipt") {
		t.Errorf("nil report summary = %q, want not covered", none)
	}
	if GeneratedSummary(nil, report) != "" {
		t.Error("summary without groups should be empty")
	}
	once := AppendGeneratedSummary("review\n", groups, report)
	if AppendGeneratedSummary(once, groups, report) != once {
		t.Error("appending twice duplicated the section")
	}
}

func TestMergeShardedPRReview_GeneratedFilesGetOneEntryPerGroup(t *testing.T) {
	var lowSignal []diffsignal.FileDiff
	all := []string{"src/a.go"}
	for i := 0; i < 20; i++ {
		p := fmt.Sprintf("fx/c%02d.html", i)
		lowSignal = append(lowSignal, diffsignal.FileDiff{Path: p, Segment: "xxxx", Reason: diffsignal.ReasonGeneratedAttr})
		all = append(all, p)
	}
	review := &ParsedReview{CoverageEntries: []CoverageEntry{{Path: "src/a.go", Evidence: "src/a.go:1"}}}
	merged, rendered := MergeShardedPRReview([]ShardReview{{ShardIndex: 0, Review: review}}, lowSignal, all, 0)
	if len(merged.CoverageEntries) != 2 {
		t.Fatalf("coverage entries = %+v, want src/a.go plus one group entry", merged.CoverageEntries)
	}
	if got := merged.CoverageEntries[1]; got.Path != "fx/*.html" || !strings.Contains(got.Evidence, "20 files") {
		t.Fatalf("group entry = %+v", got)
	}
	if strings.Contains(rendered, "c07.html") {
		t.Error("rendered review lists a grouped generated file")
	}
	generated := diffsignal.GeneratedFiles(lowSignal)
	if err := validateCoverageLedgerExcluding(merged.CoverageEntries, all, generated); err != nil {
		t.Fatalf("merged ledger invalid: %v", err)
	}
}

func TestBuildPRPrompt_GeneratedFilesLeaveTheChecklist(t *testing.T) {
	ctx := &PRContext{
		PR:             &PRInfo{Number: 743, Title: "regenerate", HeadSHA: "head", BaseSHA: "base"},
		Diff:           "diff --git a/src/a.go b/src/a.go",
		Files:          []string{"src/a.go", "fx/c00.html", "fx/c01.html"},
		GeneratedFiles: []string{"fx/c00.html", "fx/c01.html"},
		GeneratedGroups: []diffsignal.GeneratedGroup{
			{Pattern: "fx/*.html", Files: []string{"fx/c00.html", "fx/c01.html"}, Bytes: 40},
		},
	}
	prompt := BuildPRPrompt(ctx)
	if strings.Contains(prompt, "c00.html") || strings.Contains(prompt, "c01.html") {
		t.Errorf("prompt lists a generated file:\n%s", prompt)
	}
	for _, want := range []string{"`src/a.go`", "fx/*.html | 2 files |", "## Generated Files"} {
		if !strings.Contains(prompt, want) {
			t.Errorf("prompt missing %q", want)
		}
	}
	if got := ctx.LedgerFiles(); len(got) != 1 || got[0] != "src/a.go" {
		t.Errorf("LedgerFiles() = %v", got)
	}
}
